cd /mnt/c/Projects/biotech_screener/biotech-screener && python3 << 'EOF'
import json
from pathlib import Path

snap = Path("data/snapshots/2026-05-27/decision_portfolio.json")
if not snap.exists():
    print(f"✗ Snapshot not found at {snap}")
    exit(1)

df_json = json.loads(snap.read_text())
if isinstance(df_json, dict) and "data" in df_json:
    rows = df_json["data"]
elif isinstance(df_json, list):
    rows = df_json
else:
    rows = []

print(f"Total rows: {len(rows)}")

# Check expectation fields per Spec 105
expectation_fields = [
    "short_interest_pct",
    "close_price",
    "market_cap_mm",
    "priced_move_pct"
]

missing_by_field = {field: 0 for field in expectation_fields}
for row in rows:
    for field in expectation_fields:
        if field not in row or row[field] is None or row[field] == "":
            missing_by_field[field] += 1

print("\nExpectation Field Coverage (Spec 105):")
for field, missing_count in sorted(missing_by_field.items(), key=lambda x: x[1]):
    coverage = 100.0 * (len(rows) - missing_count) / len(rows) if rows else 0
    print(f"  {field}: {coverage:.1f}% ({len(rows) - missing_count}/{len(rows)})")

# Audit specific columns
print("\nSnapshot Columns (first row):")
if rows:
    for key in sorted(rows[0].keys())[:20]:
        print(f"  {key}")

print("\n✓ Snapshot validation complete")
EOF

