# Check the latest snapshot diagnostics for IC information
from pathlib import Path
import json

snapshot = Path("data/snapshots/2026-05-27")
if snapshot.exists():
    # Look for forward eval or IC files
    for f in snapshot.glob("*ic*"):
        print(f"Found: {f.name}")

    # Check audit directory
    audit_dir = snapshot / "audit"
    if audit_dir.exists():
        print("\nAudit files:")
        for f in audit_dir.iterdir():
            print(f"  {f.name}")
            if "forward" in f.name.lower() or "ic" in f.name.lower():
                content = f.read_text()[:300]
                print(f"    Preview: {content}")

# Read from logs instead
logs = Path("logs")
if logs.exists():
    prod_log = logs / "daily_production_2026-05-27.log"
    if prod_log.exists():
        content = prod_log.read_text()
        # Find forward eval lines
        for line in content.split('\n'):
            if "forward" in line.lower() and ("ic" in line.lower() or "mean" in line.lower()):
                print(f"\nLog entry: {line.strip()}")

EOF

